// How much extra vertical scroll distance is "spent" per pixel of
// horizontal travel. >1 means the section stays pinned longer, so the
// horizontal motion feels slower/more controlled relative to the wheel.
const SCROLL_SPEED = 1.25;

function usePrefersReducedMotion() {
    const [reduced, setReduced] = useState(false);
    useEffect(() => {
        const mq = window.matchMedia("(prefers-reduced-motion: reduce)");
        setReduced(mq.matches);
        const listener = (e) => setReduced(e.matches);
        mq.addEventListener("change", listener);
        return () => mq.removeEventListener("change", listener);
    }, []);
    return reduced;
}

/* ------------------------------------------------------------------ */
/*  useHorizontalScroll.js  (inlined)                                 */
/*                                                                     */
/*  Pin-and-translate pattern: the outer <section> is made tall        */
/*  enough to hold the horizontal travel distance as extra vertical    */
/*  scroll room. The inner wrapper is `position: sticky; top: 0`, so   */
/*  it stays pinned to the viewport while that extra room scrolls by.  */
/*  Each scroll tick, we read how far we've scrolled *through* the     */
/*  section and map that 0..1 progress directly onto translateX for    */
/*  the card track — so scrolling down visibly pushes the cards left.  */
/* ------------------------------------------------------------------ */
function usePinnedHorizontalScroll(cardCount, reducedMotion) {
    const sectionRef = useRef(null); // tall outer wrapper (scroll runway)
    const stickyRef = useRef(null); // pinned viewport-height wrapper
    const trackRef = useRef(null); // flex row of cards, gets translateX
    const cardRefs = useRef([]);

    const [translateX, setTranslateX] = useState(0);
    const [maxTranslate, setMaxTranslate] = useState(0);
    const [activeIndex, setActiveIndex] = useState(0);
    const [progressList, setProgressList] = useState(
        () => new Array(cardCount).fill(0)
    );

    const rafRef = useRef(null);
    const hoverLockRef = useRef(null); // index of card currently hovered/focused

    cardRefs.current = useMemo(() => [], [cardCount]);

    const setCardRef = useCallback((el, index) => {
        if (el) cardRefs.current[index] = el;
    }, []);

    // How far the track can travel = track width minus the visible width.
    const recalcMax = useCallback(() => {
        const track = trackRef.current;
        const sticky = stickyRef.current;
        if (!track || !sticky) return;
        const trackWidth = track.scrollWidth;
        const viewportWidth = sticky.clientWidth;
        setMaxTranslate(Math.max(0, trackWidth - viewportWidth));
    }, []);

    // Read scroll position, convert to translateX + active-card state.
    const measure = useCallback(() => {
        if (reducedMotion) return; // fallback path scrolls natively instead
        const section = sectionRef.current;
        const sticky = stickyRef.current;
        if (!section || !sticky) return;

        const total = maxTranslate * SCROLL_SPEED;
        const rect = section.getBoundingClientRect();
        const scrolledPast = -rect.top; // px scrolled since section entered
        const progress = total > 0 ? clamp(scrolledPast / total, 0, 1) : 0;
        const x = -progress * maxTranslate;
        setTranslateX(x);

        // active card = whichever card is nearest the sticky viewport's center
        const stickyRect = sticky.getBoundingClientRect();
        const centerX = stickyRect.left + stickyRect.width / 2;

        let closestIndex = 0;
        let closestDistance = Infinity;
        const nextProgress = [];

        cardRefs.current.forEach((card, i) => {
            if (!card) {
                nextProgress.push(0);
                return;
            }
            const cardRect = card.getBoundingClientRect();
            const cardCenter = cardRect.left + cardRect.width / 2;
            const distance = cardCenter - centerX;

            if (Math.abs(distance) < closestDistance) {
                closestDistance = Math.abs(distance);
                closestIndex = i;
            }
            nextProgress.push(clamp(distance / stickyRect.width, -1, 1));
        });

        setActiveIndex(
            hoverLockRef.current !== null ? hoverLockRef.current : closestIndex
        );
        setProgressList(nextProgress);
    }, [maxTranslate, reducedMotion]);

    const schedule = useCallback(() => {
        if (rafRef.current) cancelAnimationFrame(rafRef.current);
        rafRef.current = requestAnimationFrame(measure);
    }, [measure]);

    const handleCardEnter = useCallback(
        (index) => {
            hoverLockRef.current = index;
            schedule();
        },
        [schedule]
    );

    const handleCardLeave = useCallback(() => {
        hoverLockRef.current = null;
        schedule();
    }, [schedule]);

    // Scroll the *page* so the given card ends up centered — used for
    // keyboard navigation (Arrow keys) since the cards no longer own
    // their own scroll container.
    const scrollToIndex = useCallback(
        (index) => {
            const card = cardRefs.current[index];
            const section = sectionRef.current;
            const sticky = stickyRef.current;
            if (!card || !section || !sticky) return;

            if (reducedMotion) {
                card.scrollIntoView({
                    behavior: "smooth",
                    inline: "center",
                    block: "nearest",
                });
                return;
            }

            const targetX = clamp(
                card.offsetLeft - sticky.clientWidth / 2 + card.clientWidth / 2,
                0,
                maxTranslate
            );
            const progress = maxTranslate > 0 ? targetX / maxTranslate : 0;
            const total = maxTranslate * SCROLL_SPEED;
            const sectionTop =
                section.getBoundingClientRect().top + window.scrollY;
            window.scrollTo({
                top: sectionTop + progress * total,
                behavior: "smooth",
            });
        },
        [maxTranslate, reducedMotion]
    );

    useLayoutEffect(() => {
        recalcMax();
        const track = trackRef.current;
        if (!track || typeof ResizeObserver === "undefined") return;
        const observer = new ResizeObserver(() => {
            recalcMax();
            schedule();
        });
        observer.observe(track);
        return () => observer.disconnect();
    }, [recalcMax, schedule]);

    useEffect(() => {
        if (reducedMotion) return;
        measure();
        window.addEventListener("scroll", schedule, { passive: true });
        window.addEventListener("resize", schedule);
        return () => {
            window.removeEventListener("scroll", schedule);
            window.removeEventListener("resize", schedule);
            if (rafRef.current) cancelAnimationFrame(rafRef.current);
        };
    }, [measure, schedule, reducedMotion]);

    const sectionHeight = reducedMotion
        ? "auto"
        : `calc(100vh + ${maxTranslate * SCROLL_SPEED}px)`;

    const pinProgress = useMemo(() => {
        if (reducedMotion || maxTranslate === 0) return 0;
        return clamp(-translateX / maxTranslate, 0, 1);
    }, [translateX, maxTranslate, reducedMotion]);

    return {
        sectionRef,
        stickyRef,
        trackRef,
        setCardRef,
        activeIndex,
        progressList,
        translateX,
        sectionHeight,
        pinProgress,
        handleCardEnter,
        handleCardLeave,
        scrollToIndex,
    };
}

function clamp(value, min, max) {
    return Math.min(max, Math.max(min, value));
}

/* ------------------------------------------------------------------ */
/*  StrategyCard.jsx  (inlined)                                       */
/* ------------------------------------------------------------------ */
const StrategyCard = React.memo(function StrategyCard({
    directive,
    index,
    isActive,
    progress,
    reducedMotion,
    setCardRef,
    onEnter,
    onLeave,
    onKeyNav,
}) {
    const { code, title, description, Icon } = directive;
    const parallax = reducedMotion ? 0 : progress * 15; // -15px .. +15px



    return (
        <div
            ref={(el) => setCardRef(el, index)}
            tabIndex={0}
            role="group"
            aria-label={`${code}: ${title}`}
            aria-current={isActive ? "true" : undefined}
            onMouseEnter={() => onEnter(index)}
            onMouseLeave={onLeave}
            onFocus={() => onEnter(index)}
            onBlur={onLeave}
            onKeyDown={(e) => onKeyNav(e, index)}
            className="sd-card bg-white"
            style={{
                height: "80vh",
                width: 320,
                border: "1px solid #1b1b1b",
                borderRadius: 10,
                overflow: "hidden",
                position: "relative",
                padding: 32,
                display: "flex",
                flexDirection: "column",
                justifyContent: "space-between",
                cursor: "pointer",

            }}
        >
            {/* four corner accents */}
            {["tl", "tr", "bl", "br"].map((corner) => (
                <span
                    key={corner}
                    aria-hidden="true"
                    className={`sd-corner sd-corner-${corner}`}
                    style={{
                        opacity: isActive ? 1 : 0,
                        transition: reducedMotion
                            ? "none"
                            : "opacity 350ms ease, transform 350ms ease",
                    }}
                />
            ))}

            {/* top row */}
            <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", zIndex: 2 }}>
                <div
                    style={{

                        borderRadius: 10,
                        border: "1px solid #262626",
                        display: "flex",
                        alignItems: "center",
                        justifyContent: "center",
                        color: "#e5e5e5",
                    }}
                // className="w-[200px] h-[200px]"
                >
                    {/* {Icon} */}


                </div>
                <span
                    style={{
                        fontFamily: "'JetBrains Mono', monospace",
                        fontSize: 12,
                        letterSpacing: "0.12em",

                    }}


                >
                    {code}
                </span>
            </div>

            {/* middle illustration */}
            <div
                style={{
                    position: "absolute",
                    inset: 0,
                    bottom: "100px",
                    display: "flex",
                    alignItems: "center",
                    justifyContent: "center",
                    pointerEvents: "none",
                    transform: `translateX(${parallax}px)`,
                    transition: reducedMotion ? "none" : "transform 120ms linear",
                }}


            >
                {Icon}
            </div>

            {/* bottom text */}
            <div style={{ zIndex: 2 }}>
                <div
                    style={{
                        height: 1,
                        background: "#1b1b1b",
                        marginBottom: 20,
                    }}
                />
                <h3
                    style={{
                        fontSize: 22,
                        fontWeight: 600,
                        color: "#000",
                        marginBottom: 10,
                        letterSpacing: "-0.01em",
                    }}
                >
                    {title}
                </h3>
                <p
                    style={{
                        fontSize: 14,
                        lineHeight: 1.6,
                        color: "#242424",
                    }}
                >
                    {description}
                </p>
            </div>
        </div>
    );
});

/* ------------------------------------------------------------------ */
/*  StrategicDirectives.jsx  (main export)                            */
/* ------------------------------------------------------------------ */
function StrategicDirectives() {
    const reducedMotion = usePrefersReducedMotion();
    const {
        sectionRef,
        stickyRef,
        trackRef,
        setCardRef,
        activeIndex,
        progressList,
        translateX,
        sectionHeight,
        pinProgress,
        handleCardEnter,
        handleCardLeave,
        scrollToIndex,
    } = usePinnedHorizontalScroll(DIRECTIVES.length, reducedMotion);

    const handleKeyNav = useCallback(
        (e, index) => {
            if (e.key === "ArrowRight") {
                e.preventDefault();
                scrollToIndex(Math.min(index + 1, DIRECTIVES.length - 1));
            } else if (e.key === "ArrowLeft") {
                e.preventDefault();
                scrollToIndex(Math.max(index - 1, 0));
            } else if (e.key === "Enter") {
                scrollToIndex(index);
            }
        },
        [scrollToIndex]
    );

    return (
        <section
            id="strategy"
            ref={sectionRef}
            style={{
                width: "100%",
                background: "#000000",
                color: "#ffffff",
                height: sectionHeight,
                position: "relative",
                animation: reducedMotion ? "none" : "sd-section-in 800ms ease both",
            }}
        >
            <style>{`
        @keyframes sd-section-in {
          from { opacity: 0; transform: translateY(24px); }
          to { opacity: 1; transform: translateY(0); }
        }
        @keyframes sd-heading-in {
          from { opacity: 0; transform: translateY(28px); }
          to { opacity: 1; transform: translateY(0); }
        }
        @keyframes sd-line-in {
          from { width: 0; opacity: 0; }
          to { width: 80px; opacity: 1; }
        }
        @keyframes sd-card-in {
          from { opacity: 0; transform: translateY(40px); }
          to { opacity: 1; transform: translateY(0); }
        }
        .sd-card:hover .sd-corner,
        .sd-card:focus-visible .sd-corner {
          opacity: 1 !important;
        }
        .sd-track::-webkit-scrollbar { display: none; }
        .sd-corner {
          position: absolute;
          width: 18px;
          height: 18px;
          z-index: 3;
        }
        .sd-corner::before, .sd-corner::after {
          content: "";
          position: absolute;
          background: #000;
          box-shadow: 0 0 12px rgba(59,130,246,0.7);
        }
        .sd-corner-tl { top: 14px; left: 14px; }
        .sd-corner-tr { top: 14px; right: 14px; }
        .sd-corner-bl { bottom: 14px; left: 14px; }
        .sd-corner-br { bottom: 14px; right: 14px; }
        .sd-corner-tl::before, .sd-corner-tr::before, .sd-corner-bl::before, .sd-corner-br::before {
          width: 18px; height: 2px; top: 0;
        }
        .sd-corner-tl::after, .sd-corner-tr::after, .sd-corner-bl::after, .sd-corner-br::after {
          width: 2px; height: 18px; top: 0;
        }
        .sd-corner-tl::before { left: 0; }
        .sd-corner-tl::after { left: 0; }
        .sd-corner-tr::before { right: 0; }
        .sd-corner-tr::after { right: 0; top: 0; }
        .sd-corner-bl::before { left: 0; bottom: 0; top: auto; }
        .sd-corner-bl::after { left: 0; }
        .sd-corner-br::before { right: 0; bottom: 0; top: auto; }
        .sd-corner-br::after { right: 0; }
        @media (prefers-reduced-motion: reduce) {
          .sd-card { animation: none !important; transition: none !important; }
        }
        @media (max-width: 767px) {
          .sd-card { width: 90vw !important; min-width: 90vw !important;  }
        }
        @media (min-width: 768px) and (max-width: 1023px) {
          .sd-card { width: 360px !important; min-width: 360px !important; }
        }
      `}</style>
            <div
                style={{

                    margin: "0 auto",
                    width: "100%",



                    flexShrink: 0,
                }}
                className="mb-[10px] xl:mb-[56px] py-5 md:py-10 px-[10px] xl:px-[24px]"
            >

                {/* FAQ Header */}
                <div className=" mx-auto max-w-[1500px] text-center md:text-start">
                    <h2 className="font-semibold text-3xl sm:text-4xl lg:text-5xl leading-tight text-white mb-4">
                        Strategic Directives
                    </h2>
                    <p className="text-gray-400 text-base md:text-lg max-w-3xl leading-relaxed">
                        CodeSarthi is a unified developer workspace that eliminates tool fatigue by merging real-time communication,AI Based interview project management, and automated resume generation into a single platform driven by high-bandwidth collaboration and deep human-AI synergy.

                    </p>
                </div>




            </div>
            <div
                ref={stickyRef}
                style={{
                    position: reducedMotion ? "relative" : "sticky",
                    top: 0,

                    width: "100vw",
                    display: "flex",
                    flexDirection: "column",
                    justifyContent: "start",
                    overflow: "hidden",

                }}
                className="h-auto lg:pt-10 xl:pt-20"
            >
                {/* header */}


                {/* card track — either transform-driven (pinned scroll) or a
            native horizontally-scrollable row (reduced-motion fallback,
            so we don't force scroll-jacking on people who've asked for
            less motion) */}
                <div
                    className="sd-track"
                    role="list"
                    aria-label="Strategic directives"
                    style={{
                        display: "flex",
                        gap: 32,
                        padding: "8px 24px 24px",
                        width: "100%",
                        overflowX: reducedMotion ? "auto" : "visible",
                        scrollSnapType: reducedMotion ? "x mandatory" : "none",
                        msOverflowStyle: "none",
                        scrollbarWidth: "none",
                    }}
                >
                    <div
                        ref={trackRef}
                        style={{
                            display: "flex",
                            gap: 32,
                            transform: reducedMotion ? "none" : `translateX(${translateX}px)`,
                            willChange: reducedMotion ? "auto" : "transform",
                            margin: " auto",
                        }}
                        className=" px-10 lg:px-40"
                    >
                        {DIRECTIVES.map((directive, i) => (
                            <StrategyCard
                                key={directive.id}
                                directive={directive}
                                index={i}
                                isActive={i === activeIndex}
                                progress={progressList[i] || 0}
                                reducedMotion={reducedMotion}
                                setCardRef={setCardRef}
                                onEnter={handleCardEnter}
                                onLeave={handleCardLeave}
                                onKeyNav={handleKeyNav}
                            />
                        ))}
                    </div>
                </div>

                {/* progress indicator — reinforces that scrolling the page is
            what's driving the horizontal motion */}
                {!reducedMotion && (
                    <div
                        aria-hidden="true"
                        style={{
                            width: 80,
                            height: 2,
                            background: "#1b1b1b",
                            margin: "24px auto 0",
                            borderRadius: 2,
                            overflow: "hidden",
                            flexShrink: 0,
                        }}
                    >
                        <div
                            style={{
                                height: "100%",
                                width: `${pinProgress * 100}%`,
                                background: "#3B82F6",
                                boxShadow: "0 0 8px rgba(59,130,246,0.7)",
                            }}
                        />
                    </div>
                )}
            </div>
        </section>
    );
}




